// Định nghĩa thư viện STOMP chuẩn chạy độc lập trong trình duyệt
window.Stomp = {
    over: function (wsConnection) {
        var client = { ws: wsConnection, counter: 0, connected: false };
        
        client.connect = function (headers, connectCallback, errorCallback) {
            // Nếu kết nối qua SockJS, lắng nghe sự kiện onopen
            client.ws.onopen = function () {
                client.ws.send("CONNECT\naccept-version:1.1,1.2\n\n\0");
            };
            
            // Trường hợp SockJS đã tự động mở kết nối trước đó
            if (client.ws.readyState === 1) {
                client.ws.send("CONNECT\naccept-version:1.1,1.2\n\n\0");
            }

            client.ws.onmessage = function (evt) {
                var data = evt.data || "";
                if (data.startsWith("CONNECTED")) {
                    client.connected = true;
                    if (connectCallback) connectCallback();
                } else if (client.onMessageReceivedCallback) {
                    client.onMessageReceivedCallback(evt);
                }
            };
        };

        client.subscribe = function (destination, callback) {
            var id = "sub-" + client.counter++;
            client.ws.send("SUBSCRIBE\nid:" + id + "\ndestination:" + destination + "\n\n\0");
            
            client.onMessageReceivedCallback = function (evt) {
                var data = evt.data || "";
                // Bóc tách phần thân tin nhắn nằm sau 2 dấu xuống dòng (\n\n) của giao thức STOMP
                var parts = data.split("\n\n");
                var bodyData = parts.length > 1 ? parts[1].replace(/\0$/, "") : "";
                if (callback) callback({ body: bodyData });
            };
        };

        client.send = function (destination, headers, body) {
            client.ws.send("SEND\ndestination:" + destination + "\n\n" + body + "\0");
        };

        return client;
    }
};